INSERT INTO `document_templates` (`id`, `template_name`, `document_type`, `certificate_type_id`, `template_content`, `is_active`, `created_by`, `updated_by`, `created_at`, `updated_at`, `file_data`, `file_encoding`) VALUES
(1, 'Default Barangay Clearance', 'barangay_clearance', NULL, '{\"title\":\"BARANGAY CLEARANCE\",\"header_text\":\"TO WHOM IT MAY CONCERN:\",\"main_content\":\"This is to certify that the person whose name, signature, thumb marks and other personal data appearing hereon, has requested for a Barangay Clearance from this Office and the results are listed below.\",\"footer_text\":\"This is to further certify that {resident_name} is a bona fide resident of this Barangay. {resident_name} is known to me with a good moral character, law abiding citizen in the community. {resident_name} has no criminal record found in our Barangay Records.\",\"signature_text\":\"Given this {issued_date}\",\"validity_text\":\"Valid until: {valid_until}\",\"location\":\"Barangay Batia, Bocaue, Bulacan\",\"show_qr_code\":true,\"show_control_number\":true,\"font_family\":\"Times-Roman\",\"font_size\":12}', 0, 1, NULL, '2025-12-11 19:34:27', '2025-12-11 19:34:27', , 'application/pdf'),
(2, 'Default Indigency Certificate', 'indigency_certificate', 19, '{\"title\":\"CERTIFICATE OF INDIGENCY\",\"header_text\":\"TO WHOM IT MAY CONCERN,\",\"main_content\":\"This is to certify that {resident_name}, {age} years old, with address at {address}, is belonging to the Indigent Family in our Barangay.\",\"additional_content\":\"As per records of this office, subject person has NO DEROGATORY RECORDS.\",\"footer_text\":\"This certification is issued upon the request of the above person to be used for his/her {purpose}, {specific_purpose}.\",\"signature_text\":\"Given this {issued_date} at Batia, Municipality of Bocaue, Bulacan.\",\"validity_text\":\"Valid until: {valid_until}\",\"location\":\"Batia, Municipality of Bocaue, Bulacan\",\"show_qr_code\":false,\"show_control_number\":true,\"font_family\":\"Times-Roman\",\"font_size\":12}', 1, 1, NULL, '2025-12-11 19:34:27', '2025-12-11 19:34:27', NULL, NULL),
(3, 'updated barangay clearance', 'barangay_clearance', 4, '{\"title\":\"updated barangay clearance\",\"header_text\":\"Uploaded Template\",\"main_content\":\"This template was uploaded as a file.\",\"footer_text\":\"Generated from uploaded file\",\"location\":\"Barangay Batia, Bocaue, Bulacan\",\"show_qr_code\":true,\"show_control_number\":true,\"font_family\":\"Times-Roman\",\"font_size\":12}', 1, 4, 4, '2025-12-11 20:03:53', '2025-12-11 20:03:53', , 'application/pdf');
